// Validate and extract task data from webhook
const input = $input.all()[0].json;
const taskId = input.task_id || input.body?.task_id || input.query?.task_id || null;
const oldStatus = input.old_status || input.body?.old_status || null;
const newStatus = input.new_status || input.body?.new_status || input.status || null;

if (!taskId || !newStatus) {
  throw new Error('task_id and new_status are required. Received: ' + JSON.stringify(input));
}

return {
  json: {
    task_id: String(taskId).trim(),
    old_status: oldStatus,
    new_status: newStatus,
    execution_id: $execution.id || `exec_${Date.now()}`,
    workflow_name: 'Task Status Change Notifications'
  }
};

// Format notifications based on status change
const task = $node['Get Task Details'].json || {};
const statusChange = $node['Validate Task Status Change'].json || {};

const statusLabels = {
  'chua_bat_dau': 'Chưa bắt đầu',
  'dang_tien_hanh': 'Đang tiến hành',
  'hoan_thanh': 'Hoàn thành',
  'khong_hoan_thanh': 'Không hoàn thành',
  'cham_tien_do': 'Chậm tiến độ',
  'hoan_thanh_truoc_han': 'Hoàn thành trước hạn',
  'da_huy': 'Đã hủy',
  'tam_hoan': 'Tạm hoãn'
};

const statusColors = {
  'hoan_thanh': '#4CAF50',
  'hoan_thanh_truoc_han': '#4CAF50',
  'khong_hoan_thanh': '#f44336',
  'cham_tien_do': '#FF6B6B',
  'da_huy': '#9E9E9E',
  'tam_hoan': '#FFA500',
  'dang_tien_hanh': '#2196F3',
  'chua_bat_dau': '#9E9E9E'
};

const newStatusLabel = statusLabels[statusChange.new_status] || statusChange.new_status;
const oldStatusLabel = statusLabels[statusChange.old_status] || statusChange.old_status || 'Unknown';
const statusColor = statusColors[statusChange.new_status] || '#4ECDC4';

// Determine channel based on work_group
const workGroupChannels = {
  'bien_tap': '#tasks-bien-tap',
  'hanh_chinh': '#tasks-hanh-chinh',
  'chung': '#tasks-general',
  'default': '#tasks-general'
};

const channel = workGroupChannels[task.work_group] || workGroupChannels['default'];

// Format Mattermost message
const mattermostText = `📋 **Task Status Changed**\n\nTask **${task.title || 'Untitled'}** status has been updated.`;

const mattermostAttachments = [{
  color: statusColor,
  title: `Task: ${task.title || 'Untitled'}`,
  fields: [
    { short: true, title: 'Status', value: `${oldStatusLabel} → ${newStatusLabel}` },
    { short: true, title: 'Assignee', value: `@${task.assignee_username || 'unassigned'}` },
    { short: true, title: 'Priority', value: task.priority || 'normal' },
    { short: true, title: 'Due Date', value: task.due_date || 'N/A' }
  ],
  footer: 'OrientClassicsManager',
  ts: Math.floor(Date.now() / 1000)
}];

// Format email
const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px;">
  <h2 style="color: #333; border-bottom: 2px solid ${statusColor}; padding-bottom: 10px;">📋 Task Status Changed</h2>

  <p>The task <strong>${task.title || 'Untitled'}</strong> status has been updated:</p>

  <table style="width: 100%; border-collapse: collapse; margin: 20px 0; background: #f9f9f9;">
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; font-weight: bold;">Previous Status:</td>
      <td style="padding: 12px; border-bottom: 1px solid #ddd;">${oldStatusLabel}</td>
    </tr>
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; font-weight: bold;">New Status:</td>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; color: ${statusColor};"><strong>${newStatusLabel}</strong></td>
    </tr>
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; font-weight: bold;">Assignee:</td>
      <td style="padding: 12px; border-bottom: 1px solid #ddd;">${task.assignee_name || 'Unassigned'}</td>
    </tr>
    <tr>
      <td style="padding: 12px; font-weight: bold;">Due Date:</td>
      <td style="padding: 12px;">${task.due_date || 'N/A'}</td>
    </tr>
  </table>

  <p style="margin-top: 30px;">Best regards,<br><strong>OrientClassicsManager System</strong></p>
</div>
`;

// Determine recipients
const recipients = [];
if (task.assignee_email) recipients.push({ email: task.assignee_email, name: task.assignee_name, role: 'assignee' });
if (task.creator_email && task.creator_email !== task.assignee_email) recipients.push({ email: task.creator_email, name: task.creator_name, role: 'creator' });
if (task.supervisor_email && task.supervisor_email !== task.assignee_email && task.supervisor_email !== task.creator_email) recipients.push({ email: task.supervisor_email, name: task.supervisor_name, role: 'supervisor' });

return {
  json: {
    // Task data
    task_id: task.id,
    task_title: task.title,
    old_status: statusChange.old_status,
    new_status: statusChange.new_status,
    old_status_label: oldStatusLabel,
    new_status_label: newStatusLabel,
    status_color: statusColor,
    // Mattermost data
    mattermost_channel: channel,
    mattermost_text: mattermostText,
    mattermost_attachments: mattermostAttachments,
    // Email data
    email_html: emailHtml,
    email_subject: `📋 Task Status Changed: ${task.title || 'Untitled'} - ${newStatusLabel}`,
    recipients: recipients,
    // Execution tracking
    execution_id: statusChange.execution_id,
    workflow_name: statusChange.workflow_name
  }
};

// Format email for each recipient
const recipient = $json;
const notificationData = $node['Format Notifications'].json || {};

return {
  json: {
    to: recipient.email,
    subject: notificationData.email_subject,
    html: notificationData.email_html,
    recipient_name: recipient.name,
    recipient_role: recipient.role
  }
};
